package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

const reexecEnv = "KOGEN_SETUP_TEST_REEXEC"

// TestMain lets the test binary act as the standalone command: with reexecEnv set it runs
// main, so subprocess tests observe the real process, its streams and its exit status.
func TestMain(m *testing.M) {
	if os.Getenv(reexecEnv) == "1" {
		main()
		return
	}
	os.Exit(m.Run())
}

type commandRun struct {
	exit   int
	stdout string
	stderr string
}

func gitEnv(t *testing.T, ceiling string) []string {
	t.Helper()
	var env []string
	for _, kv := range os.Environ() {
		if strings.HasPrefix(kv, "GIT_") || strings.HasPrefix(kv, "HOME=") {
			continue
		}
		env = append(env, kv)
	}
	return append(env,
		"HOME="+t.TempDir(),
		"GIT_CONFIG_NOSYSTEM=1",
		"GIT_CONFIG_GLOBAL=/dev/null",
		"GIT_CEILING_DIRECTORIES="+ceiling,
		reexecEnv+"=1",
	)
}

func runCommand(t *testing.T, env []string, args ...string) commandRun {
	t.Helper()
	cmd := exec.Command(os.Args[0], args...)
	cmd.Env = env
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	exit := 0
	if err != nil {
		var ee *exec.ExitError
		if !errors.As(err, &ee) {
			t.Fatalf("running the command: %v", err)
		}
		exit = ee.ExitCode()
	}
	return commandRun{exit: exit, stdout: stdout.String(), stderr: stderr.String()}
}

// decodeOne decodes stdout as exactly one JSON object with the three documented fields.
func decodeOne(t *testing.T, stdout string) map[string]json.RawMessage {
	t.Helper()
	dec := json.NewDecoder(strings.NewReader(stdout))
	var fields map[string]json.RawMessage
	if err := dec.Decode(&fields); err != nil {
		t.Fatalf("stdout is not a JSON object: %v\nstdout: %q", err, stdout)
	}
	if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
		t.Fatalf("stdout holds more than one JSON value: %q", stdout)
	}
	if len(fields) != 3 {
		t.Fatalf("stdout object has fields %v, want exit, configuration and error", fields)
	}
	for _, name := range []string{"exit", "configuration", "error"} {
		if _, ok := fields[name]; !ok {
			t.Fatalf("stdout object lacks %q: %q", name, stdout)
		}
	}
	return fields
}

func TestUsageWithoutExactlyOneCheckout(t *testing.T) {
	for _, args := range [][]string{nil, {"one", "two"}} {
		r := runCommand(t, gitEnv(t, t.TempDir()), args...)
		if r.exit != 2 {
			t.Errorf("args %q: exit %d, want 2", args, r.exit)
		}
		if r.stderr != "usage: kogen-setup <checkout>\n" {
			t.Errorf("args %q: stderr %q, want the usage line", args, r.stderr)
		}
		if r.stdout != "" {
			t.Errorf("args %q: stdout %q, want no output", args, r.stdout)
		}
	}
}

func TestEmptyGitRepositoryInitializes(t *testing.T) {
	parent := t.TempDir()
	repo := filepath.Join(parent, "repo")
	if err := os.Mkdir(repo, 0o755); err != nil {
		t.Fatal(err)
	}
	env := gitEnv(t, parent)
	for _, args := range [][]string{
		{"init", "-q"},
		{"config", "user.name", "Fixture"},
		{"config", "user.email", "fixture@example.invalid"},
		{"config", "commit.gpgsign", "false"},
		{"config", "core.hooksPath", t.TempDir()},
	} {
		cmd := exec.Command("git", args...)
		cmd.Dir, cmd.Env = repo, env
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}
	r := runCommand(t, env, repo)
	if r.exit != 0 {
		t.Fatalf("exit %d, want 0\nstdout: %q\nstderr: %q", r.exit, r.stdout, r.stderr)
	}
	fields := decodeOne(t, r.stdout)
	if string(fields["exit"]) != "0" {
		t.Errorf("exit field %s, want 0", fields["exit"])
	}
	if string(fields["error"]) != "null" {
		t.Errorf("error field %s, want null", fields["error"])
	}
	var cfg struct {
		Path    string `json:"path"`
		Content string `json:"content"`
	}
	if err := json.Unmarshal(fields["configuration"], &cfg); err != nil {
		t.Fatalf("configuration field %s: %v", fields["configuration"], err)
	}
	written, err := os.ReadFile(filepath.Join(repo, ".kogen", "project.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Path != ".kogen/project.yaml" {
		t.Errorf("configuration path %q, want .kogen/project.yaml", cfg.Path)
	}
	if len(written) == 0 || cfg.Content != string(written) {
		t.Errorf("configuration content %q, want the written file %q", cfg.Content, written)
	}
	if r.stderr == "" {
		t.Errorf("stderr is empty, want Init's human-readable output there")
	}
}

func TestNotAGitRepositoryFails(t *testing.T) {
	parent := t.TempDir()
	dir := filepath.Join(parent, "plain")
	if err := os.Mkdir(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	r := runCommand(t, gitEnv(t, parent), dir)
	fields := decodeOne(t, r.stdout)
	var exit int
	if err := json.Unmarshal(fields["exit"], &exit); err != nil || exit == 0 {
		t.Errorf("exit field %s, want a nonzero integer", fields["exit"])
	}
	if r.exit != exit {
		t.Errorf("process exit %d, want the JSON exit %d", r.exit, exit)
	}
	var message *string
	if err := json.Unmarshal(fields["error"], &message); err != nil || message == nil || *message == "" {
		t.Fatalf("error field %s, want a non-null error string", fields["error"])
	}
	if string(fields["configuration"]) != "null" {
		t.Errorf("configuration field %s, want null", fields["configuration"])
	}
	if !strings.Contains(r.stderr, *message) {
		t.Errorf("stderr %q does not hold the diagnostic %q", r.stderr, *message)
	}
}

